S = {}

S['38'] = dict(tag='beyond',
simple="Some people can sell property only <span class='hl'>if certain circumstances exist</span> (for example, a guardian or manager only for necessity). If such a person sells claiming those circumstances exist, and the buyer <span class='hl'>made reasonable enquiry and acted in good faith</span>, the circumstances are treated as having existed.",
deep="""<ol><li><b>Authority dependent on variable circumstances:</b> a karta for legal necessity, a guardian for the minor's benefit, a limited owner for necessity.</li>
<li><b>Transfer for consideration</b> alleging that the circumstances exist.</li>
<li><b>Buyer's duty:</b> reasonable care to ascertain the circumstances, and good faith.</li>
<li><b>Effect:</b> as between the buyer and the transferor (and others affected, such as reversioners or heirs), the circumstances are deemed to have existed.</li>
<li>The buyer need not prove the necessity actually existed; he must prove he made proper enquiry and believed it in good faith.</li></ol>
<p><b>Act's illustration:</b> a Hindu widow sells a field claiming her income is insufficient for maintenance; B makes reasonable enquiry, is satisfied, and buys in good faith; as against the collateral heirs, necessity is deemed to have existed.</p>""",
dissect=[("authorised only under circumstances in their nature variable","Conditional authority."),("transfers such property for consideration, alleging the existence of such circumstances","Sale claiming necessity."),("after using reasonable care to ascertain the existence of such circumstances, has acted in good faith","Buyer's duty."),("be deemed to have existed","Effect.")],
master=dict(story="Arjun, karta of the Mishra joint family, sells 2 acres to Kabir saying the money is needed for his father's heart surgery. Kabir checks the hospital estimate, talks to the doctor and confirms the family has no ready cash. Later it emerges Arjun spent part of the money on a car. Arjun's son challenges the sale. In a second sale, Suresh buys from Arjun on the same claim without making any enquiry.",steps=[("Kabir's purchase?","Protected: reasonable enquiry and good faith, so necessity is deemed to have existed as against the family."),("Suresh's purchase?","Not protected: no reasonable care.")]),
ills=[("Proper enquiry","Buyer verifies the claimed necessity.","y","Protected","s.38."),("No enquiry","Buyer relies only on the seller's word.","n","Not protected","Reasonable care missing.")],
exam=dict(q="Explain s.38 with the illustration.",pts=["Conditional authority","Consideration and allegation","Reasonable care and good faith","Deemed existence"],line="Under s.38, where a person authorised only in variable circumstances transfers for consideration alleging them, they are deemed to have existed if the transferee used reasonable care and acted in good faith."),
quiz=[("A buyer from a karta who made no enquiry:",["Protected by s.38","Not protected","Protected if he paid full price"],1,"Reasonable care required.")],
links=[("s.7","Competence and authority."),("s.41","Ostensible owner.")],
next="Section 39 protects people entitled to maintenance from the property.")

S['39'] = dict(tag='beyond',
simple="If someone has a right to <span class='hl'>maintenance (or money for advancement or marriage)</span> from the income of a property, that right can be enforced against a buyer <span class='hl'>who knew about it or got the property free</span>, but not against a buyer who paid and had no notice.",
deep="""<ul><li>Right holder: wife, widow, dependent family member entitled to maintenance, or to a provision for advancement or marriage, out of the profits of immovable property.</li>
<li>Enforceable against: a transferee with notice, or a gratuitous transferee.</li>
<li>Not enforceable against: a transferee for consideration without notice, nor against the property in his hands.</li>
<li>Contrast s.6(dd): the maintenance right itself cannot be transferred.</li></ul>""",
dissect=[("a right to receive maintenance, or a provision for advancement or marriage, from the profits of immoveable property","The protected right."),("if he has notice thereof or if the transfer is gratuitous","Who is bound."),("but not against a transferee for consideration and without notice of the right","Who is not bound.")],
master=dict(story="Raghunath's widowed sister has a right to ₹10,000 a month from the farm's income. Raghunath gifts the farm to Arjun; separately he sells a second farm (also charged with her maintenance) to Kabir, who knew of it; and a third to Suresh for full price, who had no notice.",steps=[("Arjun (gift)?","Bound: gratuitous transferee."),("Kabir?","Bound: notice."),("Suresh?","Not bound: consideration and no notice.")]),
ills=[("Notice","Buyer knew of the maintenance right.","y","Bound","s.39."),("Bona fide buyer","Paid and had no notice.","n","Not bound","s.39.")],
exam=dict(q="Short note on s.39.",pts=["Maintenance from profits of property","Bound: notice or gratuitous","Not bound: bona fide purchaser for value"],line="Under s.39, a right to maintenance from the profits of immovable property may be enforced against a transferee with notice or a gratuitous transferee, but not against a transferee for consideration without notice."),
quiz=[("A donee of property charged with maintenance:",["Bound","Not bound","Bound only with notice"],0,"Gratuitous transferee.")],
links=[("s.6(dd)","Future maintenance cannot be transferred."),("s.3","Notice.")],
next="Section 40 deals with restrictions and contractual obligations attached to land.")

S['40'] = dict(tag='beyond',
simple="A neighbour's <span class='hl'>right to restrain how land is used</span> (for his own land's benefit), and a person's right under a <span class='hl'>contract attached to ownership</span> (like an agreement to sell), can be enforced against a later buyer <span class='hl'>who had notice or got it free</span>, but not against a buyer for value without notice.",
deep="""<ol><li><b>First limb (restrictive covenants):</b> a third person, for the more beneficial enjoyment of his own land, has a right to restrain the use of another's land in a particular manner, independently of any interest or easement.</li>
<li><b>Second limb:</b> a third person is entitled to the benefit of an obligation arising out of contract and annexed to the ownership of land, though not an interest or easement (for example, a contract for sale).</li>
<li><b>Enforceable against:</b> a transferee with notice, or a gratuitous transferee.</li>
<li><b>Not enforceable against:</b> a transferee for consideration without notice, nor against the property in his hands.</li></ol>
<p><b>Act's illustration:</b> A contracts to sell Sultanpur to B; while the contract is in force he sells to C, who has notice; B may enforce the contract against C. (Read with s.54: a contract for sale creates no interest, but s.40 still protects the buyer against a purchaser with notice.)</p>
<p><i>Note:</i> your Indian Kanoon copy reads "not against such property"; the correct text is "nor against".</p>""",
dissect=[("for the more beneficial enjoyment of his own immoveable property","First limb: restrictive covenant."),("an obligation arising out of contract and annexed to the ownership of immoveable property","Second limb: contractual obligation."),("a transferee with notice thereof or a gratuitous transferee","Who is bound."),("not against a transferee for consideration and without notice","Who is not bound."),("B may enforce the contract against C","Illustration.")],
master=dict(story="Raghunath sells the front half of his plot to Kabir, who covenants not to build above one floor so Raghunath's house keeps its light. Kabir resells to Suresh, who knew of the covenant. Separately, Raghunath agrees in writing to sell his orchard to Meera; before completion he sells it to Ramesh, who knew of the agreement, and a third plot under similar agreement to a stranger for full price with no notice.",steps=[("Suresh?","Bound by the height restriction: notice."),("Ramesh?","Meera can enforce her contract against him: notice (Act's illustration)."),("The stranger?","Not bound: consideration and no notice.")]),
ills=[("Restrictive covenant with notice","Later buyer knew of the one-floor limit.","y","Bound","First limb."),("Contract for sale","Second buyer knew of the earlier agreement.","y","Bound","Illustration."),("Bona fide buyer","Paid without notice.","n","Not bound","s.40.")],
exam=dict(q="Explain s.40.",pts=["Two limbs","Bound: notice or gratuitous","Not bound: purchaser for value without notice","Illustration and link with s.54"],line="Under s.40, a right to restrain the use of land for the benefit of other land, or an obligation arising out of contract annexed to ownership, may be enforced against a transferee with notice or a gratuitous transferee, but not a transferee for consideration without notice."),
quiz=[("A second buyer with notice of an earlier agreement to sell:",["Takes free","Is bound by it","Becomes co-owner"],1,"Illustration.")],
links=[("s.11","Directions protecting other land."),("s.54","A contract for sale creates no interest."),("s.3","Notice.")],
next="Section 41 protects buyers from an ostensible owner.")

S['41'] = dict(tag='syllabus',
simple="If the real owner <span class='hl'>lets someone else appear to be the owner</span>, and that person sells for value to a buyer who <span class='hl'>took reasonable care and acted in good faith</span>, the real owner <span class='hl'>cannot cancel the sale</span>.",
deep="""<ol><li><b>Ostensible owner:</b> a person who appears to be the owner but is not the real owner (for example, property bought benami in his name, or a relative allowed to deal as owner).</li>
<li><b>Consent of the real owner,</b> express or implied: the real owner must have allowed this appearance. Without consent (for example, a forger), s.41 does not apply.</li>
<li><b>Transfer for consideration:</b> gifts are not protected.</li>
<li><b>Buyer's duty:</b> reasonable care to ascertain that the transferor had power to transfer, and good faith.</li>
<li><b>Effect:</b> the transfer is not voidable on the ground that the transferor was not authorised.</li>
<li><b>Basis:</b> estoppel. The owner who created the false appearance cannot later deny it against an innocent buyer.</li>
<li><b>Exception to nemo dat</b> (s.7).</li></ol>""",
dissect=[("with the consent, express or implied, of the persons interested in immoveable property","Real owner's consent."),("a person is the ostensible owner of such property","Appears to be owner."),("transfers the same for consideration","Only transfers for value."),("the transfer shall not be voidable on the ground that the transferor was not authorised to make it","Effect."),("after taking reasonable care to ascertain that the transferor had power to make the transfer, has acted in good faith","Buyer's duty.")],
master=dict(story="Raghunath buys a plot in 2015 in Arjun's name (benami) and lets Arjun keep the title deeds, pay the taxes and tell everyone it is his. In 2026 Arjun sells it to Kabir for ₹30 lakh. Kabir checks the registered title, the tax receipts and the encumbrance certificate, and visits the plot. Raghunath sues to set aside the sale. In a second deal, Arjun gifts another benami plot to Meera. In a third, Suresh forges Raghunath's signature and sells Raghunath's godown to Ramesh.",steps=[("Kabir's purchase?","Protected: ostensible owner with real owner's consent, consideration, reasonable care and good faith. Raghunath cannot set it aside."),("Gift to Meera?","Not protected: no consideration."),("Ramesh's purchase from Suresh?","Not protected: Raghunath never consented to Suresh appearing as owner.")]),
ills=[("Benami","Real owner lets the benamidar hold out as owner; bona fide sale for value.","y","Protected","s.41."),("No consent","A forger sells.","n","Not protected","Consent missing."),("Gift","Ostensible owner gifts the property.","n","Not protected","Consideration missing."),("No enquiry","Buyer ignores obvious warning signs (another person in possession).","n","Not protected","Reasonable care missing.")],
exam=dict(q="Explain transfer by ostensible owner. (10 marks)",pts=["Meaning of ostensible owner","Essentials: consent, consideration, reasonable care, good faith","Effect: not voidable","Estoppel basis; exception to nemo dat"],line="Under s.41, a transfer for consideration by an ostensible owner with the real owner's consent is not voidable for want of authority, if the transferee took reasonable care and acted in good faith."),
quiz=[("A gift by an ostensible owner:",["Protected","Not protected","Voidable only by the donee"],1,"Consideration is required.")],
links=[("s.7","Nemo dat."),("s.43","Feeding the grant by estoppel."),("s.3","Notice.")],
next="Section 42 deals with a person who reserved power to revoke an earlier transfer.")

S['42'] = dict(tag='beyond',
simple="If you transfer property but <span class='hl'>keep a power to revoke</span> it, and later transfer the same property to someone else <span class='hl'>for value</span>, the later transfer itself acts as a <span class='hl'>revocation</span> of the first, to the extent of the power and subject to its conditions.",
deep="<p>The second transfer for consideration operates as an exercise of the reserved power, subject to any condition on its exercise. <b>Act's illustration:</b> A lets a house to B, reserving power to revoke if a specified surveyor opines B's use is harmful; A, thinking so, lets to C; this revokes B's lease subject to the surveyor's opinion.</p>",
dissect=[("reserving power to revoke the transfer","Power reserved."),("subsequently transfers the property for consideration to another transferee","Later transfer for value."),("subject to any condition attached to the exercise of the power","Conditions still apply."),("as a revocation of the former transfer to the extent of the power","Effect.")],
master=dict(story="Raghunath leases a shop to Ramesh, reserving power to revoke if a named engineer certifies that Ramesh's use is damaging the building. Believing it is, Raghunath leases the shop to Kabir.",steps=[("Effect of the lease to Kabir?","It operates as revocation of Ramesh's lease, but only if the engineer certifies the damage.")]),
ills=[("Condition met","Engineer certifies damage.","y","Revoked","s.42."),("Condition not met","Engineer finds no damage.","n","Not revoked","Subject to the condition.")],
exam=dict(q="Short note on s.42.",pts=["Reserved power to revoke","Later transfer for value revokes","Subject to conditions"],line="Under s.42, a later transfer for consideration by one who reserved power to revoke an earlier transfer operates as a revocation to the extent of the power, subject to its conditions."),
quiz=[("Does the later transfer revoke if the power's condition is unmet?",["Yes","No","Only partly"],1,"Subject to the condition.")],
links=[("s.48","Priority.")],
next="Section 43 sets out the doctrine of feeding the grant by estoppel.")

S['43'] = dict(tag='syllabus',
simple="If someone <span class='hl'>falsely or mistakenly claims</span> he can transfer a property, takes payment, and <span class='hl'>later actually acquires</span> that property, the buyer can <span class='hl'>choose</span> to take it, as long as the contract still subsists. Innocent later buyers without notice are protected. This is <span class='hl'>feeding the grant by estoppel</span>.",
deep="""<ol><li><b>Representation:</b> the transferor fraudulently or erroneously represents that he is authorised to transfer certain immovable property (\"fraudulently\" added in 1929).</li>
<li><b>Professes to transfer for consideration:</b> gifts are not covered.</li>
<li><b>Later acquisition:</b> the transferor afterwards acquires an interest in that property.</li>
<li><b>Option of the transferee:</b> the transfer operates on that later interest at the transferee's option (he may instead rescind and claim his money back).</li>
<li><b>While the contract subsists:</b> if the transferee has already rescinded, the option is gone.</li>
<li><b>Protection:</b> the rights of later transferees in good faith for consideration without notice of the option are not impaired.</li>
<li><b>Basis:</b> estoppel; the transferor cannot deny his own representation. The later title \"feeds\" the earlier grant.</li>
<li><b>Link to s.6(a):</b> even a spes successionis sold on a representation of present ownership can be fed when the property is later acquired.</li></ol>
<p><b>Act's illustration:</b> A, separated from his father B, sells fields X, Y, Z representing he is authorised; Z belongs to B; on B's death A inherits Z; C, not having rescinded, may require A to deliver Z.</p>""",
dissect=[("fraudulently or erroneously represents that he is authorised to transfer","Representation, fraud or mistake."),("professes to transfer such property for consideration","For value only."),("at the option of the transferee","Transferee chooses."),("operate on any interest which the transferor may acquire in such property","Later-acquired interest."),("at any time during which the contract of transfer subsists","Contract must still be alive."),("shall impair the right of transferees in good faith for consideration without notice of the existence of the said option","Protection of later bona fide buyers.")],
master=dict(story="In 2026 Arjun tells Kabir the Athagarh farm is already his (it is still Raghunath's) and sells it to Kabir for ₹50 lakh. Kabir does not rescind. In 2030 Raghunath dies and Arjun inherits the farm. In 2031, Arjun sells the same farm to Suresh, who pays full price and has no idea of Kabir's deal. In a separate matter, Arjun gifted (without consideration) another of his father's plots to Meera in 2026 on a similar representation.",steps=[("Kabir's position in 2030?","At his option, the 2026 sale now operates on Arjun's inherited interest: Arjun must convey the farm to Kabir."),("Suresh in 2031?","If Suresh truly bought in good faith, for value, without notice of Kabir's option, s.43 does not impair his rights. Kabir is left with his remedies against Arjun. (Kabir should have acted on the option before Suresh bought.)"),("Meera's gift?","s.43 does not apply: no consideration."),("What if Kabir had rescinded in 2028 and taken his money back?","No option remains: the contract no longer subsists.")]),
ills=[("Erroneous representation","Seller honestly but wrongly thinks the land is his; later acquires it.","y","Buyer can claim","Erroneous covered."),("Fraudulent representation","Seller lies; later acquires.","y","Buyer can claim","Fraudulently added 1929."),("Gift","Donor misrepresents; later acquires.","n","Not covered","Consideration required."),("Rescinded","Buyer took his money back first.","n","No option","Contract must subsist."),("Later bona fide buyer","Third party buys for value without notice after the acquisition.","n","s.43 does not override him","Protection clause."),("Spes successionis","Heir sells expected inheritance claiming present ownership; later inherits.","y","Buyer can claim","Link with s.6(a).")],
exam=dict(q="Explain the doctrine of feeding the grant by estoppel. (10 marks)",pts=["Ingredients: representation, consideration, later acquisition, option, subsisting contract","Protection of later bona fide transferees","Estoppel basis","Relation with s.6(a)","Illustration"],line="Under s.43, where a person fraudulently or erroneously represents authority to transfer immovable property and professes to transfer it for consideration, the transfer operates, at the transferee's option, on any interest he later acquires while the contract subsists."),
quiz=[("s.43 applies to a gift?",["Yes","No","Only if registered"],1,"Consideration required."),("Who has the option under s.43?",["Transferor","Transferee","Court"],1,"At the option of the transferee.")],
links=[("s.6(a)","Spes successionis."),("s.41","Ostensible owner."),("s.7","Nemo dat.")],
next="Section 44 begins the rules on co-owners.")
